import {Engine,ELEMENTS,COLORS,ICONS,distance} from './engine.js';
import {Audio} from './audio.js';
const $=id=>document.getElementById(id),canvas=$('map'),ctx=canvas.getContext('2d');
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const title=e=>e.charAt(0).toUpperCase()+e.slice(1),num=n=>Number(n).toLocaleString(undefined,{maximumFractionDigits:1});
let data,game,tab='build',selected=null,placing=null,buildCell=null,moving=null,hover=null,background=null,transform,uiSignature='',last=performance.now(),lastUI=0,lastSave=0,savedAvailable=false,toastTimer,toastMessage=null,pendingUpgrade=null,researchOpen=false,elementSignature='';
const audio=new Audio(),towerSheet=new Image(),enemySheet=new Image(),starterSheet=new Image();towerSheet.src='assets/towers.png';enemySheet.src='assets/enemies.png';starterSheet.src='assets/starters.png';
try{const response=await fetch('data/game.json');if(!response.ok)throw Error(`Game data returned HTTP ${response.status}`);data=await response.json();game=new Engine(data,{seed:430});window.elementGame=game;checkSave();renderAll();$('setup').showModal();requestAnimationFrame(frame);}catch(error){document.body.innerHTML='<div class="error-screen"><h1>Could not load the frontier</h1><p>'+esc(error.message)+'</p><p>Run this game through an HTTP server or Netlify. Upload the extracted repository with its dist folder and netlify.toml.</p><button onclick="location.reload()">Retry</button></div>';}
function notify(text,error=false){toastMessage=text;$('mapHint').textContent=text;$('toast').textContent=text;$('toast').style.borderColor=error?'#e9a57c':'#9bbc70';$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>{toastMessage=null;$('toast').classList.remove('show');},3500);}
function result(r){if(!r.ok){notify(r.error,true);return false;}uiSignature='';renderAll();return true;}
function imageStyle(def){if(def.element==='composite'&&def.name!=='Periodic Tower of the Elements'){const col=def.name.includes('Cannon')?1:0,row=def.name.startsWith('Super')?2:def.name.startsWith('Advanced')?1:0;return `background-image:url('assets/starters.png');background-size:200% 300%;background-position:${col*100}% ${row*50}%`;}const col=def.element==='composite'?3:Math.max(0,ELEMENTS.indexOf(def.element)),row=def.name==='Periodic Tower of the Elements'?2:Math.min(2,Math.max(0,def.tier-1));return `background-position:${col*20}% ${row*50}%`;}
function requirements(def){return Object.entries(def.requirements).map(([e,n])=>`${title(e)} ${n}`).join(' + ')||def.elements.map(title).join(' + ')||'Composite';}
function cancelBuild(){pendingUpgrade=null;buildCell=null;placing=null;document.querySelector('main').classList.remove('build-target');setDockExpanded(false);renderAll();}
function confirmBuild(){if(!buildCell||!placing)return;const r=game.build(game.player,placing,buildCell.x,buildCell.y);if(!r.ok){notify(r.error,true);renderAll();return;}cancelBuild();notify('Tower built. Tap another grid cell to build again.');}
function panelBuild(){const p=game.player,base=['h01T','h01W','n003','h001','n005','n008','n004','n000','n02G'];document.querySelector('main').classList.toggle('build-target',!!buildCell);if(!buildCell)return '<div class="build-prompt"><strong>Tap a grid cell to build</strong><span>Tap a tower to upgrade or sell.</span></div>';return '<div class="tower-grid">'+base.filter(id=>game.allowed(p,game.defs[id]).ok).map(id=>{const d=game.defs[id],gate=game.allowed(p,d),reason=!gate.ok?gate.error:p.gold<d.cost?'Need '+d.cost+' gold.':'',locked=!!reason;return `<button class="tower-card ${placing===id?'active':''}" data-build="${id}" ${locked?'disabled':''} aria-pressed="${placing===id}" title="${esc(reason||d.ability)}"><span class="sprite" style="${imageStyle(d)}"></span><strong>${esc(d.name.replace(' Tower',''))}</strong><span class="price">◈ ${num(d.cost)}</span>${locked?'<span class="lock">LOCKED</span>':''}</button>`;}).join('')+'</div><div class="build-actions">'+(placing?'<button id="confirmBuild" class="primary">Build '+esc(game.defs[placing].name.replace(' Tower',''))+' · '+num(game.defs[placing].cost)+' ◈</button>':'<span>Choose a tower for this cell</span>')+'<button id="cancelBuild">Cancel</button></div>';}
function researchChoices(){const p=game.player,random=['AR','SR'].includes(game.options.selection);return '<div class="panel-heading"><h3>The six powers</h3><span class="eyebrow">'+p.lumber+' LUMBER</span></div><p class="panel-text">'+(random?'Random mode spends lumber on guardians automatically. Defeat each guardian to unlock its element.':'Spend one lumber to summon a guardian. Defeat it to unlock that element’s next level. Earn lumber every five waves.')+'</p><div class="element-grid">'+ELEMENTS.map(e=>{const level=p.elements[e],summoned=p.enemies.some(v=>v.boss&&v.element===e);return `<button class="element-choice" data-summon="${e}" ${random||level===3||summoned?'disabled':''}><span class="e-icon" style="color:${COLORS[e]}">${ICONS[e]}</span><b>${title(e)}</b><small>${summoned?'Guardian in battle':level===3?'Mastered':'Summon level '+(level+1)+' · 1 lumber'}</small><div class="levels">${[1,2,3].map(n=>`<span class="${level>=n?'lit':''}"></span>`).join('')}</div></button>`;}).join('')+'</div><div class="economy-card"><div><strong>Compound interest · '+p.interest+'%</strong><small>Gain gold every 15 seconds.</small></div><button id="raiseInterest" '+(p.interestUpgrades>=3?'disabled':'')+'>+1% · 1 lumber</button></div><div class="economy-card"><div><strong>Pure Essence</strong><small>Defeat its guardian for a Pure tower slot.</small></div><button id="summonEssence">1 lumber</button></div>'+(game.options.selection==='DP'?'<p class="panel-text" style="margin-top:12px">Draft restrictions: five dual and seven triple families were eliminated for this seed. Check the Library for available branches.</p>':'');}
function libraryRows(query=''){const p=game.player;return data.towers.filter(d=>(d.name+' '+d.elements.join(' ')).toLowerCase().includes(query.toLowerCase())).map(d=>`<button class="library-row" data-library="${d.id}"><span>${esc(d.name)}<small>${esc(requirements(d))}${game.banned.has(d.id)?' · DRAFT BANNED':''}</small></span><span class="price">${num(d.cost)} ◈</span></button>`).join('');}
function panelLibrary(){return '<div class="panel-heading"><h3>134 defenses</h3><span class="eyebrow">4.3b DATABASE</span></div><p class="panel-text">Inspect the original costs, damage, range, abilities, requirements, and upgrade branches.</p><input id="search" class="library-search" type="search" placeholder="Search towers or elements…" aria-label="Search towers"><div class="library-list" id="libraryList">'+libraryRows()+'</div>';}
function setDockExpanded(expanded){document.querySelector("main").classList.toggle("dock-expanded",expanded);$("dockSize").textContent=expanded?"Less ↓":"More ↑";$("dockSize").setAttribute("aria-expanded",String(expanded));}
$("dockSize").onclick=()=>setDockExpanded(!document.querySelector("main").classList.contains("dock-expanded"));
function renderPanel(){$('panel').innerHTML=panelBuild();document.querySelectorAll('[data-build]').forEach(b=>b.onclick=()=>{if(!buildCell)return;if(placing===b.dataset.build){confirmBuild();return;}placing=b.dataset.build;selected=null;setDockExpanded(false);renderAll();});if($('confirmBuild'))$('confirmBuild').onclick=confirmBuild;if($('cancelBuild'))$('cancelBuild').onclick=cancelBuild;}
function openResearch(focusInterest=false){selected=null;cancelBuild();researchOpen=true;renderResearch();if(focusInterest)$('raiseInterest').scrollIntoView({block:'nearest'});}
function closeResearch(){researchOpen=false;$('researchPanel').hidden=true;}
function renderResearch(){if(!researchOpen)return;$('researchPanel').hidden=false;$('researchPanel').innerHTML='<div class="research-header"><strong>Element research & economy</strong><button id="closeResearch" aria-label="Close research controls">Close ×</button></div>'+researchChoices();$('closeResearch').onclick=closeResearch;document.querySelectorAll('[data-summon]').forEach(b=>b.onclick=()=>{audio.start();result(game.summon(game.player,b.dataset.summon));renderResearch();});$('raiseInterest').onclick=()=>{result(game.interestUpgrade(game.player));renderResearch();};$('summonEssence').onclick=()=>{result(game.essenceResearch(game.player));renderResearch();};}
function guardianDisplaySites(){const lane=data.lanes[0],sites=game.buildingSites(game.player).filter(s=>s.x>lane.exit[0]&&s.y>lane.exit[1]);return [0,1,2,4,5,7].map(i=>sites[i]||sites.at(-1));}
function updateElementSprites(){const p=game.player,key=Object.values(p.elements).join();if(key===elementSignature)return;elementSignature=key;$('elementHUD').hidden=!ELEMENTS.some(e=>p.elements[e]>0);$('elementSprites').innerHTML=ELEMENTS.map((element,col)=>{const level=p.elements[element],guardian=data.bosses.find(b=>b.element===element&&b.tier===level);return `<span class="element-badge ${level?'unlocked':'locked'}" data-element="${element}" data-level="${level}" data-guardian="${guardian?.id||''}" title="${guardian?.name||title(element)} · Level ${level}"><span class="element-sprite" style="background-image:url('assets/enemies.png');background-size:600% 400%;background-position:${col*20}% 100%;filter:brightness(${1+Math.max(0,level-1)*.12})"></span><small>${level?['','I','II','III'][level]:''}</small></span>`;}).join('');$('elementHUD').setAttribute('aria-label','Obtained guardians: '+ELEMENTS.filter(e=>p.elements[e]>0).map(e=>title(e)+' level '+p.elements[e]).join(', '));positionMapHUD();}
function positionMapHUD(){if(!transform||!game)return;const r=canvas.getBoundingClientRect(),frame=document.querySelector('.battlefield').getBoundingClientRect(),f=Math.min(r.width/canvas.width,r.height/canvas.height),left=r.left-frame.left+(r.width-canvas.width*f)/2,top=r.top-frame.top+(r.height-canvas.height*f)/2,slots=guardianDisplaySites(),size=190*transform.scale*f,first=screen(slots[0].x,slots[0].y),last=screen(slots.at(-1).x,slots.at(-1).y);$('elementHUD').style.left=(left+first.x*f-size/2)+'px';$('elementHUD').style.top=(top+first.y*f-size*.65)+'px';$('elementHUD').style.width=((last.x-first.x)*f+size)+'px';$('elementHUD').style.height=(size+10)+'px';document.querySelectorAll('#elementSprites .element-badge').forEach((badge,i)=>{const pos=screen(slots[i].x,slots[i].y);badge.style.left=((pos.x-first.x)*f)+'px';badge.style.width=size+'px';badge.querySelector('.element-sprite').style.height=size+'px';});$('interestHUD').style.left=(left+6)+'px';$('interestHUD').style.top=(top+8)+'px';}
$('summonGuardians').onclick=()=>researchOpen?closeResearch():openResearch();$('interestHUD').onclick=()=>openResearch(true);new ResizeObserver(positionMapHUD).observe(canvas);
function showLibrary(){ $('libraryContent').innerHTML=panelLibrary()+'<section id="libraryDetails" aria-live="polite"><p>Select a tower to view its stats and upgrade branches.</p></section>';$('search').oninput=()=>{$('libraryList').innerHTML=libraryRows($('search').value);bindLibrary();};bindLibrary();$('libraryModal').showModal();}
function bindLibrary(){document.querySelectorAll('[data-library]').forEach(b=>b.onclick=()=>{const d=game.defs[b.dataset.library];$('libraryDetails').innerHTML=`<div class="selected-head"><span class="selected-sprite" style="${imageStyle(d)}"></span><div><h3>${esc(d.name)}</h3><small>${esc(requirements(d))}</small></div></div><div class="stat-grid"><span>COST<b>${num(d.cost)} ◈</b></span><span>DAMAGE<b>${d.displayDamage==='None'?'Ability':num(d.damage)}</b></span><span>RANGE<b>${num(d.range)}</b></span><span>INTERVAL<b>${num(d.interval)}s</b></span></div><p class="ability-text">${esc(d.ability==='None'?'Standard elemental attack.':d.ability)}</p><div class="upgrade-list">${d.upgrades.map(id=>`<button data-library="${id}" class="upgrade-button">${esc(game.defs[id].name)} · ${num(game.defs[id].cost)} ◈</button>`).join('')||'No further upgrades.'}</div>`;bindLibrary();});}
$('openLibrary').onclick=showLibrary;
function renderInspector(){const p=game.player,t=p.towers.find(v=>v.id===selected),d=t?game.defs[t.type]:null;document.querySelector('main').classList.toggle('inspecting',!!d);if(!d){$('inspector').innerHTML='<div class="empty"><span>✧</span><h3>Your defense starts here.</h3><p>Build Arrow and Cannon towers first. Tap Summon to summon an elemental guardian, then defeat it to unlock elemental towers.</p></div>';return;}
 const multiplier=t?game.multiplier(t):1,upgrades=d.upgrades.map(id=>game.defs[id]);$('inspector').innerHTML=`<div class="selected-head"><span class="selected-sprite" style="${imageStyle(d)}"></span><div><span class="eyebrow">${t?'TOWER #'+t.id:'TOWER DATABASE'}</span><h3>${esc(d.name)}</h3><small>${esc(requirements(d))} · ${d.id}</small></div></div><div class="stat-grid"><span>DAMAGE<b>${d.displayDamage==='None'?'Ability':num(d.damage*multiplier)}</b></span><span>ATTACK INTERVAL<b>${num(d.interval)}s</b></span><span>RANGE<b>${num(d.range)}</b></span></div><p class="ability-text">${esc(d.ability==='None'?'Standard elemental attack.':d.ability)}</p>${t?'<div class="target-row"><label for="targeting">Target priority</label><select id="targeting">'+[['first','First'],['strong','Strongest'],['weak','Weakest'],['last','Last'],['near','Nearest']].map(([v,n])=>`<option value="${v}" ${t.targetMode===v?'selected':''}>${n}</option>`).join('')+'</select></div>':''}<div class="upgrade-list">${upgrades.map(u=>{const gate=game.allowed(p,u),disabled=t?(!gate.ok||p.gold<u.cost||!!t.cloneTTL):false;return `<button class="upgrade-button" ${disabled?'disabled':''} data-upgrade="${u.id}"><span>${esc(u.name)}<small>${esc(gate.ok?requirements(u):gate.error)}</small></span><span class="price">${num(u.cost)} ◈</span></button>`;}).join('')}</div>${t?`<div class="selected-actions"><button id="sellTower" ${t.cloneTTL?'disabled':''}>Sell · ${game.refund(p,t)} ◈ (${Math.round(game.refundRate(t)*100)}%)</button>${['tidal','magic','oblivion','clone'].includes(d.family)?'<button id="castTower">'+(d.family==='tidal'?'Douse · '+t.charge:d.family==='oblivion'?'Reload':d.family==='magic'?'Magic boost':'Conjure')+'</button>':''}${d.family==='golem'?'<button id="moveTower">Move</button>':''}</div>`:`<p class="panel-text" style="margin-top:12px">Build/upgrade step: ${num(d.cost)} gold${d.essence?' · '+d.essence+' Pure Essence':''}. Ability damage may be additional to the displayed attack damage.</p>`}`;
 if(t&&pendingUpgrade){const next=game.defs[pendingUpgrade];$('inspector').querySelector('.upgrade-list').insertAdjacentHTML('beforebegin',`<div class="upgrade-preview"><strong>${esc(next.name)}</strong><p>Damage ${num(next.damage)} · Interval ${num(next.interval)}s · Range ${num(next.range)}</p><div class="build-actions"><button id="confirmUpgrade" class="primary">Upgrade · ${num(next.cost)} ◈</button><button id="cancelUpgrade">Cancel</button></div></div>`);$('confirmUpgrade').onclick=()=>{const r=game.upgrade(p,t.id,pendingUpgrade);if(r.ok)pendingUpgrade=null;result(r);};$('cancelUpgrade').onclick=()=>{pendingUpgrade=null;renderInspector();};}
 if(t){$('targeting').onchange=()=>{t.targetMode=$('targeting').value;};$('sellTower').onclick=()=>{if(result(game.sell(p,t.id))){selected=null;cancelBuild();}};if($('castTower'))$('castTower').onclick=()=>result(game.cast(p,t.id));if($('moveTower'))$('moveTower').onclick=()=>{moving=t.id;notify('Click walkable ground to move the golem.');};}
 document.querySelectorAll('[data-upgrade]').forEach(b=>b.onclick=()=>{if(t){audio.start();pendingUpgrade=b.dataset.upgrade;renderInspector();$('inspector').querySelector('.upgrade-preview').scrollIntoView({block:'nearest'});}});}
function renderAll(){renderPanel();renderInspector();updateHUD();}
function updateHUD(){const p=game.player;updateElementSprites();$('gold').textContent=Math.floor(p.gold);$('lumber').textContent=p.lumber;$('lives').textContent=p.lives;$('essence').textContent=p.essence;$('interest').textContent=p.interest+'%';$('interestIn').textContent=Math.ceil(p.interestClock)+'s';$('waveLabel').textContent=game.wave===0?'PREPARATION':game.wave===61?'RONALD FINALE':`WAVE ${game.wave} / 60`;$('modeLabel').textContent=game.options.selection+' · '+data.difficulty.names[p.difficulty-1].toUpperCase();const wave=game.roster[game.wave-1];$('enemyName').textContent=game.waveName;$('enemyStats').textContent=wave?`${title(wave.element)} · ${num(Math.floor(wave.base_wave_hp*game.hpMultiplier(p)))} HP · ${wave.traits.join(', ')||'Standard'} · ${p.enemies.filter(e=>!e.boss&&!e.image).length} active`:game.wave===61?`${p.ronaldKills} defeated · Stage ${game.ronaldStage+1}`:'30 enemies per wave · 60 waves + Ronald finale';const next=game.roster[game.wave];$('nextEnemy').textContent=next?.name||'Ronald finale';$('nextStats').textContent=next?`${title(next.element)} · ${next.traits.join(', ')||'Standard'}`:'Endless survival';$('pause').textContent=game.paused?'▶ Resume':'Ⅱ Pause';$('speed').textContent=game.speed+'×';$('send').disabled=game.finished||!!game.spawning||game.wave===61|| (game.wave>0&&game.nextIn===null&&p.enemies.some(e=>!e.boss&&!e.image&&e.wave===game.wave));$('send').textContent=game.finished?'Trial ended':game.wave===61?'Ronald finale':game.spawning?'Wave spawning…':game.nextIn!==null?(game.wave===0?'▶ Begin wave 1 · ':'▶ Next wave · ')+Math.ceil(Math.max(0,game.nextIn))+'s':game.wave===0?'▶ Begin wave 1':'▶ Begin wave '+(game.wave+1);$('mapHint').textContent=toastMessage|| (moving?'Click walkable ground to move your golem.':placing?'Preview: '+game.defs[placing].name+' · Confirm below':buildCell?'Choose a tower for the highlighted cell.':'Tap a grid cell to build · Tap a tower to upgrade.');$('gameOver').hidden=!game.finished;if(game.finished){$('ending').textContent=game.ending;$('endStats').textContent=`${p.kills} enemies defeated · ${p.leaks} leaks · ${Math.floor(game.time/60)} minutes played`;}
 const signature=[tab,p.gold,p.lumber,p.essence,Object.values(p.elements).join(),p.towers.map(t=>t.id+':'+t.type).join(),p.enemies.filter(e=>e.boss).map(e=>e.id).join()].join('|');if(signature!==uiSignature){uiSignature=signature;renderPanel();if(researchOpen)renderResearch();if(selected!==null)renderInspector();}
 const lines=game.logs.slice(-30).map(l=>`<div class="log-line"><span style="color:#607755">${Math.floor(l.time/60)}:${String(Math.floor(l.time%60)).padStart(2,'0')}</span> ${esc(l.text)}</div>`).join('');if($('journal').innerHTML!==lines){$('journal').innerHTML=lines;$('journal').scrollTop=$('journal').scrollHeight;}}
function drawBackground(){const lane=data.lanes[0],bounds=game.mapBounds();canvas.height=Math.round(canvas.width*(bounds[3]-bounds[1])/(bounds[2]-bounds[0]));background=document.createElement('canvas');background.width=canvas.width;background.height=canvas.height;const c=background.getContext('2d');c.imageSmoothingEnabled=false;const scale=Math.min(canvas.width/(bounds[2]-bounds[0]),canvas.height/(bounds[3]-bounds[1]));const offsetX=(canvas.width-(bounds[2]-bounds[0])*scale)/2,offsetY=(canvas.height-(bounds[3]-bounds[1])*scale)/2;transform={scale,x:offsetX,y:offsetY,left:bounds[0],top:bounds[3]};c.fillStyle='#192b20';c.fillRect(0,0,canvas.width,canvas.height);positionMapHUD();
 function hash(x,y){return Math.abs(Math.sin(x*23.13+y*53.21)*43758.5453)%1;}
 for(let y=0;y<lane.height;y++)for(let x=0;x<lane.width;x++){const flags=lane.grid[y*lane.width+x],pt=screen(lane.origin[0]+x*32,lane.origin[1]+(y+1)*32),n=hash(x,y);c.fillStyle=flags&2?(n>.5?'#253e2b':'#223726'):flags&8?(n>.5?'#82784d':'#8b8055'):(n>.5?'#47643a':'#49693c');c.fillRect(Math.floor(pt.x),Math.floor(pt.y),Math.ceil(32*scale)+1,Math.ceil(32*scale)+1);if(flags&2&&n>.985){c.fillStyle='#152c1d';c.fillRect(pt.x-5,pt.y-7,17,17);c.fillStyle='#34573c';c.fillRect(pt.x-3,pt.y-9,13,10);c.fillStyle='#456a41';c.fillRect(pt.x,pt.y-11,7,5);}else if(!(flags&8)&&n>.9){c.fillStyle='#75905b66';c.fillRect(pt.x+2,pt.y+2,2,2);}}
 c.lineCap='square';c.lineJoin='miter';c.beginPath();lane.path.forEach(([x,y],i)=>{const p=screen(x,y);i?c.lineTo(p.x,p.y):c.moveTo(p.x,p.y);});c.strokeStyle='#5a5937';c.lineWidth=100*scale;c.stroke();c.strokeStyle='#948657';c.lineWidth=64*scale;c.stroke();c.setLineDash([2,11]);c.strokeStyle='#c3b27455';c.lineWidth=2;c.stroke();c.setLineDash([]);
 const spawn=screen(...lane.spawn),exit=screen(...lane.exit);c.fillStyle='#a1d8bc';c.font='10px ui-monospace';c.textAlign='center';c.fillText('SPAWN',spawn.x,spawn.y-24);c.fillStyle='#e1c77f';c.fillText('EXIT',exit.x,exit.y-24);
 c.strokeStyle='#719665';c.lineWidth=2;c.strokeRect(spawn.x-12,spawn.y-15,24,24);c.strokeStyle='#c1a969';c.strokeRect(exit.x-12,exit.y-15,24,24);}
function screen(x,y){return {x:transform.x+(x-transform.left)*transform.scale,y:transform.y+(transform.top-y)*transform.scale};}
function worldFromPointer(e){const r=canvas.getBoundingClientRect(),factor=Math.min(r.width/canvas.width,r.height/canvas.height),left=(r.width-canvas.width*factor)/2,top=(r.height-canvas.height*factor)/2;const sx=(e.clientX-r.left-left)/factor,sy=(e.clientY-r.top-top)/factor;return {x:transform.left+(sx-transform.x)/transform.scale,y:transform.top-(sy-transform.y)/transform.scale};}
function drawTower(t,ghost=false){const d=game.defs[t.type],p=screen(t.x,t.y),col=d.element==='composite'?3:Math.max(0,ELEMENTS.indexOf(d.element)),row=d.name==='Periodic Tower of the Elements'?2:Math.min(2,Math.max(0,d.tier-1)),size=115*transform.scale;ctx.save();ctx.globalAlpha=ghost?.65:t.cloneTTL?.65:1;if(d.element==='composite'&&d.name!=='Periodic Tower of the Elements'&&starterSheet.complete&&starterSheet.naturalWidth){const cw=starterSheet.naturalWidth/2,ch=starterSheet.naturalHeight/3,c=d.name.includes('Cannon')?1:0,r=d.name.startsWith('Super')?2:d.name.startsWith('Advanced')?1:0;ctx.drawImage(starterSheet,c*cw,r*ch,cw,ch,p.x-size/2,p.y-size*.85,size,size);}else if(towerSheet.complete&&towerSheet.naturalWidth){const cw=towerSheet.naturalWidth/6,ch=towerSheet.naturalHeight/3;ctx.drawImage(towerSheet,col*cw,row*ch,cw,ch,p.x-size/2,p.y-size*.85,size,size);}else{ctx.fillStyle=COLORS[d.element];ctx.fillRect(p.x-12,p.y-22,24,28);}
 if(d.elements.length>1){d.elements.forEach((e,i)=>{ctx.fillStyle=COLORS[e];ctx.fillRect(p.x-size/2+4+i*5,p.y+4,4,3);});}
 if(d.element==='composite'&&d.name==='Periodic Tower of the Elements'){ctx.fillStyle='#e1d7a9';ctx.font='bold 13px monospace';ctx.textAlign='center';ctx.fillText('✦',p.x,p.y-size*.43);}
 if(t.id===selected){ctx.strokeStyle=COLORS[d.element];ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(p.x,p.y+3,size*.45,size*.15,0,0,Math.PI*2);ctx.stroke();}ctx.restore();}
function drawEnemy(e){const p=screen(e.x,e.y),col=e.element==='composite'?Math.abs(e.wave||1)%6:Math.max(0,ELEMENTS.indexOf(e.element)),row=e.boss||e.ronald||/golem|giant|abomination/i.test(e.name)?3:/wolf|dragon|drake|hydra|beast|rat|harpy|quillboar/i.test(e.name)?2:/slime|watery|minion/i.test(e.name)?0:1,size=(e.boss?190:e.ronald?165:125)*transform.scale,bob=Math.sin(game.time*8+e.id)*1.5;ctx.save();if(e.boss&&!e.essenceBoss)ctx.filter=`brightness(${1+((e.tier||1)-1)*.12})`;ctx.globalAlpha=e.resurrecting>0?.3:e.image?.5:1;if(enemySheet.complete&&enemySheet.naturalWidth){const cw=enemySheet.naturalWidth/6,ch=enemySheet.naturalHeight/4;ctx.drawImage(enemySheet,col*cw,row*ch,cw,ch,p.x-size/2,p.y-size*.65+bob,size,size);}else{ctx.fillStyle=COLORS[e.element];ctx.fillRect(p.x-6,p.y-8,12,14);}const width=Math.max(18,size*.7);ctx.fillStyle='#0e1b14';ctx.fillRect(p.x-width/2,p.y-size*.72-5,width,3);ctx.fillStyle=e.boss?'#e6be65':COLORS[e.element];ctx.fillRect(p.x-width/2,p.y-size*.72-5,width*clamp(e.hp/e.maxHp,0,1),3);if(e.shield>0){ctx.strokeStyle='#8ae7ff';ctx.beginPath();ctx.arc(p.x,p.y-5,size*.52,0,Math.PI*2);ctx.stroke();}if(e.status.stun){ctx.fillStyle='#fff0bd';ctx.fillText('✧',p.x,p.y-size);}if(e.boss){ctx.textAlign='center';ctx.fillStyle='#fff1b9';ctx.font='8px monospace';ctx.fillText(e.essenceBoss?'ESSENCE':title(e.element)+' '+e.tier,p.x,p.y+size*.3);}ctx.restore();}
function clamp(v,a,b){return Math.max(a,Math.min(b,v));}
function draw(){if(!background)drawBackground();ctx.imageSmoothingEnabled=false;ctx.drawImage(background,0,0);const p=game.player;
 ctx.strokeStyle=placing?'#c5e7aa66':'#b9d09b24';ctx.lineWidth=.7;for(const cell of game.buildingSites(p)){const pos=screen(cell.x,cell.y),size=96*transform.scale;ctx.strokeRect(pos.x-size/2,pos.y-size/2,size,size);}ctx.lineWidth=1;

 if(buildCell){const pos=screen(buildCell.x,buildCell.y),size=96*transform.scale;ctx.fillStyle='#c5ed9855';ctx.strokeStyle='#e5ffc0';ctx.lineWidth=2;ctx.fillRect(pos.x-size/2,pos.y-size/2,size,size);ctx.strokeRect(pos.x-size/2,pos.y-size/2,size,size);ctx.lineWidth=1;}
 const t=p.towers.find(t=>t.id===selected);if(t){const pos=screen(t.x,t.y);ctx.fillStyle=COLORS[game.defs[t.type].element]+'14';ctx.strokeStyle=COLORS[game.defs[t.type].element]+'55';ctx.beginPath();ctx.arc(pos.x,pos.y,game.defs[t.type].range*transform.scale,0,Math.PI*2);ctx.fill();ctx.stroke();}
 const objects=[...p.towers.map(t=>({kind:'tower',item:t})),...p.enemies.filter(e=>!e.dead).map(e=>({kind:'enemy',item:e}))].sort((a,b)=>b.item.y-a.item.y);for(const {kind,item} of objects)kind==='tower'?drawTower(item):drawEnemy(item);
 for(const e of game.effects){const pos=screen(e.x,e.y),q=Math.max(0,e.ttl/e.maxTTL);ctx.save();ctx.globalAlpha=q;ctx.strokeStyle=e.color;ctx.fillStyle=e.color;if(['shot','beam','helix','boomerang'].includes(e.type)){const end=screen(e.tx,e.ty);if(e.type==='beam'||e.type==='helix'){ctx.lineWidth=e.type==='helix'?4:2;ctx.beginPath();ctx.moveTo(pos.x,pos.y-12);ctx.lineTo(end.x,end.y);ctx.stroke();}else{const progress=1-q;ctx.fillRect(pos.x+(end.x-pos.x)*progress-2,pos.y+(end.y-pos.y)*progress-2,4,4);}}else{const radius=(e.radius||110)*transform.scale*(1-q*.5);ctx.lineWidth=2;ctx.beginPath();ctx.arc(pos.x,pos.y,radius,0,Math.PI*2);ctx.stroke();if(e.type==='death'){for(let i=0;i<6;i++){const a=i*Math.PI/3;ctx.fillRect(pos.x+Math.cos(a)*radius,pos.y+Math.sin(a)*radius,3,3);}}}ctx.restore();}
 if(placing&&buildCell){const d=game.defs[placing],{x,y}=buildCell,point=screen(x,y),valid=game.validPlacement(p,x,y).ok;ctx.fillStyle=valid?'#c5ed9855':'#ff785c55';ctx.strokeStyle=valid?'#d3f6a8':'#ff947a';ctx.lineWidth=2;ctx.fillRect(point.x-48*transform.scale,point.y-48*transform.scale,96*transform.scale,96*transform.scale);ctx.strokeRect(point.x-48*transform.scale,point.y-48*transform.scale,96*transform.scale,96*transform.scale);ctx.lineWidth=1;ctx.fillStyle=valid?'#b9e08b24':'#f68b6324';ctx.strokeStyle=valid?'#b9e08b':'#f68b63';ctx.beginPath();ctx.arc(point.x,point.y,d.range*transform.scale,0,Math.PI*2);ctx.fill();ctx.stroke();drawTower({type:placing,x,y,id:-1},true);}
 if(game.paused){ctx.fillStyle='#0b1b16aa';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.fillStyle='#d8e4c6';ctx.font='24px Georgia';ctx.textAlign='center';ctx.fillText('Paused',canvas.width/2,canvas.height/2);}}
function frame(now){const elapsed=Math.min((now-last)/1000,.1);last=now;let remaining=elapsed*game.speed;if(!$('setup').open&&!$('help').open&&!$('libraryModal').open){while(remaining>0){const dt=Math.min(remaining,.05);game.step(dt);remaining-=dt;}}
 draw();for(const e of game.events.splice(0)){audio.play(e);if(e.type==='unlock')notify(e.element?`${title(e.element)} unlocked.`:'Pure Essence earned.');}if(now-lastUI>200){updateHUD();lastUI=now;}if(now-lastSave>5000){saveGame();lastSave=now;}requestAnimationFrame(frame);}
function serialize(){const keys=['options','seed','seq','time','wave','nextIn','spawning','roster','ronaldStage','ronaldInitialized','finished','ending','sharedPicks','autoplay','logs'];const state=Object.fromEntries(keys.map(k=>[k,game[k]]));state.banned=[...game.banned];state.clearedWaves=[...game.clearedWaves];state.players=game.players.map(p=>({...p,clears:[...p.clears],siteCache:undefined,enemies:p.enemies.map(e=>({...e,dots:e.dots.map(d=>({...d,tower:d.tower?{id:d.tower.id}:null})),napalm:e.napalm.map(m=>({...m,tower:m.tower?{id:m.tower.id}:null}))}))}));return {schema:1,source:data.sourceSha256,state};}
function saveGame(){if(!game||game.time===0||$('setup').open)return;try{localStorage.setItem('etd-save',JSON.stringify(serialize()));savedAvailable=true;}catch{/* Storage may be unavailable in private browsing. */}}
function checkSave(){try{const s=JSON.parse(localStorage.getItem('etd-save'));savedAvailable=s?.schema===1&&s.source===data.sourceSha256&&!s.state.finished;}catch{}$('loadSave').hidden=!savedAvailable;}
function loadGame(){try{closeResearch();elementSignature='';const s=JSON.parse(localStorage.getItem('etd-save'));if(s.schema!==1||s.source!==data.sourceSha256)throw Error('Saved run is from a different version.');game=new Engine(data,s.state.options);Object.assign(game,s.state);game.players.forEach(p=>{p.clears=new Set(p.clears);p.codeActive=false;for(const e of p.enemies){for(const d of [...e.dots,...e.napalm])d.tower=p.towers.find(t=>t.id===d.tower?.id)||null;}});game.banned=new Set(s.state.banned);game.clearedWaves=new Set(s.state.clearedWaves);game.paused=false;game.speed=1;game.effects=[];game.events=[];window.elementGame=game;background=null;placing=null;buildCell=null;pendingUpgrade=null;moving=null;selected=null;tab='build';setDockExpanded(false);document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));uiSignature='';$('setup').close();audio.start();renderAll();notify('Saved run restored.');}catch(e){notify('Could not restore save: '+e.message,true);}}
function showHelp(content){$('helpContent').innerHTML=content;$('help').showModal();}
function showDraft(){const roots=n=>data.towers.filter(t=>Object.keys(t.requirements).length===n&&Object.values(t.requirements).every(v=>v===1));showHelp('<h2>Choose the forbidden branches</h2><p>Eliminate five dual-element and seven triple-element families for this solo draft. Their upgraded forms are eliminated too. Seeded choices are selected initially.</p><form id="draftForm">'+[2,3].map(n=>'<h3>'+ (n===2?'Dual towers — choose five':'Triple towers — choose seven')+'</h3><div class="draft-grid">'+roots(n).map(t=>'<label><input type="checkbox" name="bans" value="'+t.id+'" '+(game.banned.has(t.id)?'checked':'')+'> '+esc(t.name.replace(' Tower',''))+'</label>').join('')+'</div>').join('')+'<button class="primary wide">Confirm draft & begin</button></form>');$('draftForm').onsubmit=e=>{e.preventDefault();const ids=new FormData(e.target).getAll('bans');const dual=ids.filter(id=>Object.keys(game.defs[id].requirements).length===2).length,triple=ids.length-dual;if(dual!==5||triple!==7){notify('Choose exactly five dual and seven triple families.',true);return;}game.setDraft(ids);game.log('Solo draft confirmed: five dual and seven triple branches eliminated.');$('help').close();renderAll();};}
$('setupForm').onsubmit=e=>{e.preventDefault();closeResearch();elementSignature='';const form=new FormData(e.target);game=new Engine(data,{difficulty:+form.get('difficulty'),selection:form.get('selection'),length:form.get('length'),chaos:form.has('chaos'),extreme:form.has('extreme'),seed:+form.get('seed')||430});window.elementGame=game;selected=null;placing=null;buildCell=null;pendingUpgrade=null;moving=null;tab='build';setDockExpanded(false);document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));background=null;uiSignature='';audio.start();audio.setMusic(form.has('music'));$('setup').close();renderAll();if(game.options.selection==='DP')showDraft();try{localStorage.removeItem('etd-save');}catch{}notify('Tap a grid cell to build. Earn your first elemental pick after wave 5.');};
$('resume').onclick=()=>$('setup').close();$('loadSave').onclick=loadGame;$('menu').onclick=()=>{saveGame();checkSave();$('setup').showModal();};$('again').onclick=()=>{checkSave();$('setup').showModal();};$('sound').onclick=()=>{audio.start();audio.enabled=!audio.enabled;$('sound').textContent=audio.enabled?'♪ Sound on':'♪ Muted';};$('send').onclick=()=>{audio.start();result(game.startWave());};$('pause').onclick=()=>{game.paused=!game.paused;updateHUD();};$('speed').onclick=()=>{game.speed=game.speed===1?2:game.speed===2?4:1;updateHUD();};$('clearLog').onclick=()=>{game.logs=[];updateHUD();};
$('guide').onclick=()=>showHelp('<h2>Defend the frontier</h2><ol><li><strong>Build a starter defense.</strong> Tap a green grid cell, select Arrow or Cannon, then tap Build or the same tower choice again to confirm. You begin with 70 gold.</li><li><strong>Summon an element.</strong> Tap Summon and spend lumber to summon a guardian. Defeat the guardian to unlock Fire, Nature, Earth, Light, Darkness, or Water.</li><li><strong>Follow upgrade branches.</strong> Select a built tower. Amplified single-element towers combine into dual towers; dual towers branch into triple towers.</li><li><strong>Keep gold working.</strong> Interest pays every 15 seconds. Spend lumber to increase the rate, or save it for another element.</li><li><strong>Survive 60 waves.</strong> Leaks lose lives and return with their remaining health. After wave 60, survive the Ronald finale.</li></ol><p>Fire → Nature → Earth → Light → Darkness → Water → Fire. Attacks deal 2× against the next element, 0.5× against the previous, and 0.8× against Composite.</p><p>Space pauses, Escape cancels placement, and the speed button cycles 1×/2×/4×. Touch controls work the same way. Progress saves automatically in this browser.</p>');
$('fidelity').onclick=()=>showHelp('<h2>Recreation notes</h2><p>This game uses the uploaded Element TD Survivor 4.3b map’s tower names, recipes, costs, attack stats, enemy roster, HP tables, damage matrix, bosses, terrain/pathing grid, and economy formulas. Art and audio are newly created.</p><div class="warning"><strong>It is a close browser recreation, not a verified exact port.</strong><p>Warcraft native pathfinding/collision, projectile geometry, spell timing, buff behavior, and several complex abilities are approximated. Draft uses solo elimination choices rather than multiplayer voting. Only single-player modes are included.</p></div><p>All 134 defense records are inspectable in the Library. See the repository’s FIDELITY.md for implemented mechanics and known differences. Your saved game stays in your browser.</p>');
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;selected=null;pendingUpgrade=null;buildCell=null;placing=null;document.querySelector('main').classList.remove('build-target');document.querySelectorAll('[data-tab]').forEach(v=>v.classList.toggle('active',v===b));setDockExpanded(tab!=='build');renderAll();});
canvas.onpointermove=e=>{if(transform)hover=worldFromPointer(e);};canvas.onpointerleave=()=>hover=null;canvas.onclick=e=>{if(!transform||game.finished)return;audio.start();closeResearch();const point=worldFromPointer(e);if(moving){if(result(game.moveGolem(game.player,moving,point.x,point.y)))moving=null;return;}const tappedCell=game.snapPlacement(game.player,point.x,point.y);const nearest=game.player.towers.filter(t=>{const cell=game.snapPlacement(game.player,t.x,t.y);return cell.x===tappedCell.x&&cell.y===tappedCell.y;}).sort((a,b)=>distance(a,point)-distance(b,point))[0];if(nearest){pendingUpgrade=null;setDockExpanded(true);buildCell=null;placing=null;selected=nearest.id;tab='build';document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));renderAll();document.querySelector('.dock-scroll').scrollTop=0;return;}const cell=game.snapPlacement(game.player,point.x,point.y),valid=game.validPlacement(game.player,cell.x,cell.y);if(!valid.ok){cancelBuild();selected=null;renderAll();notify(valid.error,true);return;}buildCell=cell;placing=null;selected=null;tab='build';document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));setDockExpanded(false);renderAll();document.querySelector('.dock-scroll').scrollTop=0;};document.onkeydown=e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||$('setup').open||$('help').open||$('libraryModal').open)return;if(e.code==='Space'){e.preventDefault();game.paused=!game.paused;updateHUD();}if(e.key==='Escape'){closeResearch();moving=null;selected=null;cancelBuild();}};window.addEventListener('pagehide',saveGame);
$('cycle').innerHTML=ELEMENTS.map((e,i)=>`<span class="cycle-item"><b style="color:${COLORS[e]}">${ICONS[e]}</b>${title(e)}</span>${i<5?'<span class="cycle-arrow">→</span>':''}`).join('');

